@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Source Serif 4";
  font-weight: 400;
  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #26302f;
  background: #f7f8f6;
}

a {
  color: inherit;
}

/* Header and main share one centered content width, so their edges line up. */
.site-header,
.hero {
  max-width: 1120px;
  margin: 0 auto;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px 28px;
  padding: 22px 64px;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 20px;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 28px;
}

.site-nav a {
  text-decoration: none;
  white-space: nowrap;
}

/* Two columns: the intro and the routes on the left, the search form on the right. */
.hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  grid-template-areas:
    "text   search"
    "routes search";
  align-items: start;
  column-gap: 64px;
  padding: 48px 64px 64px;
}

.hero-text {
  grid-area: text;
  max-width: 600px;
}

.search {
  grid-area: search;
}

.routes {
  grid-area: routes;
}

h1 {
  margin: 0 0 20px;
  font-family: "Source Serif 4", serif;
  font-size: 40px;
  font-weight: 400;
  line-height: 1.15;
  color: #26302f;
}

.lead {
  margin: 0 0 40px;
  font-size: 20px;
  line-height: 1.5;
}

.search {
  padding: 22px;
  border: 1px solid #dfe3e0;
  border-radius: 8px;
  background: #ffffff;
}

.search-title {
  margin-bottom: 14px;
  font-weight: 500;
}

.search label {
  display: block;
  margin-bottom: 12px;
  font-size: 14px;
  color: #5a6463;
}

.search select,
.search input {
  display: block;
  width: 100%;
  margin-top: 4px;
  padding: 8px 10px;
  border: 1px solid #8a9491;
  border-radius: 6px;
  background: #ffffff;
  font: inherit;
  font-size: 16px;
  color: #26302f;
}

.search button {
  width: 100%;
  margin-top: 6px;
  padding: 11px;
  border: 0;
  border-radius: 6px;
  background: #2d5d5a;
  color: #ffffff;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
}

h2 {
  margin: 0 0 10px;
  font-size: 16px;
  font-weight: 500;
}

.routes ul {
  max-width: 600px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.routes li {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 8px 0;
  border-top: 1px solid #dfe3e0;
}

.route-length {
  color: #5a6463;
  white-space: nowrap;
}

/* Below tablet width: one column in reading order, headline, intro, form, routes. */
@media (max-width: 820px) {
  .site-header {
    padding: 18px 24px;
  }

  .hero {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "text"
      "search"
      "routes";
    row-gap: 32px;
    padding: 24px 24px 48px;
  }

  .hero-text,
  .routes ul {
    max-width: none;
  }

  h1 {
    font-size: 32px;
  }

  .lead {
    margin-bottom: 0;
  }
}

